import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { z } from "zod";
import {
  BranchesSchema,
  CodeChangesSchema,
  CodeCheckSchema,
  CodeListingSchema,
  LaunchConfigSchema,
  LaunchConfigSummarySchema,
  PushTestResultSchema,
  RepositoriesSchema,
  RepositorySchema,
  RemovalPreviewSchema,
  SessionEventSchema,
  SessionInfoSchema,
  TailscaleStatusSchema,
} from "../src/schemas";

// Generated by real wire conversions, including nil service slices.
const fixture: Record<string, unknown> = JSON.parse(
  readFileSync(
    new URL(
      "../../internal/wire/testdata/response-arrays.json",
      import.meta.url,
    ),
    "utf8",
  ),
);

const schemas = {
  sessions: z.array(SessionInfoSchema),
  snapshot: SessionEventSchema,
  session: SessionInfoSchema,
  repository: RepositorySchema,
  repositories: RepositoriesSchema,
  branches: BranchesSchema,
  preview: RemovalPreviewSchema,
  launch: z.array(LaunchConfigSummarySchema),
  launchConfig: LaunchConfigSchema,
  check: CodeCheckSchema,
  launches: z.array(LaunchConfigSummarySchema),
  push: PushTestResultSchema,
  listing: CodeListingSchema,
  changes: CodeChangesSchema,
  // The controller adds the remaining runtime fields after wire conversion.
  tailscale: TailscaleStatusSchema.pick({ entries: true }),
};

describe("Go response arrays match the browser contract", () => {
  for (const [name, schema] of Object.entries(schemas)) {
    test(name, () => {
      expect(schema.safeParse(fixture[name]).success).toBe(true);
    });
  }
  test("unavailable repositories have empty worktrees", () => {
    expect(RepositorySchema.parse(fixture.repository).worktrees).toEqual([]);
    const repository = RepositorySchema.parse(fixture.repository);
    expect(
      RepositorySchema.safeParse({ ...repository, worktrees: null }).success,
    ).toBe(false);
  });
  test("nullable fields and required commands retain their validation", () => {
    const session = SessionInfoSchema.parse(fixture.session);
    expect(session.exitCode).toBeNull();
    expect(session.workspace).toBeNull();
    expect(SessionInfoSchema.safeParse({ ...session, cmd: null }).success).toBe(
      false,
    );
    expect(SessionInfoSchema.safeParse({ ...session, cmd: [] }).success).toBe(
      false,
    );
  });
});
